// Pseudo: dedupe by (tenantId, eventId)
function dedupe(events) {
  const seen = new Set();
  const result = [];
  for (const e of events) {
    const key = `${e.tenantId}:${e.eventId}`;
    if (!seen.has(key)) {
      seen.add(key);
      result.push(e);
    }
  }
  return result;
}
```

